struct Account {
    balance: i64,
    highest: i64,
}

impl Account {
    fn new(initial: i64) -> Account {
        Account { balance: initial, highest: initial }
    }

    fn apply(&mut self, change: i64) {
        self.balance += change;
        if self.balance > self.highest {
            self.highest = self.balance;
        }
    }
}

fn max_balance(initial: i64, changes: Vec<i64>) -> i64 {
    let mut account = Account::new(initial);
    for change in changes {
        account.apply(change);
    }
    account.highest
}

