use std::cell::RefCell;
use std::rc::Rc;

fn log_lengths(words: Vec<String>) -> Vec<i64> {
    let log: Rc<RefCell<Vec<i64>>> = Rc::new(RefCell::new(Vec::new()));
    let sink = Rc::clone(&log);
    let record = move |w: &str| sink.borrow_mut().push(w.len() as i64);
    for w in &words {
        record(w);
    }
    let out = log.borrow().clone();
    out
}

