fn swap_via_raw(mut values: Vec<i64>, i: i64, j: i64) -> Vec<i64> {
    let n = values.len() as i64;
    if i < 0 || j < 0 || i >= n || j >= n {
        return values;
    }
    let p = values.as_mut_ptr();
    // SAFETY: i and j are in bounds, so both pointers are valid and aligned; ptr::swap allows them to be equal.
    unsafe {
        std::ptr::swap(p.add(i as usize), p.add(j as usize));
    }
    values
}

